import React from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';

// Fix for default marker icons in Leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
    iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png').default,
    iconUrl: require('leaflet/dist/images/marker-icon.png').default,
    shadowUrl: require('leaflet/dist/images/marker-shadow.png').default,
});

const NYCMap = () => {
    // NYC coordinates (centered on Manhattan)
    const position = [40.7128, -74.0060];

    // Notable locations
    const locations = [
        { name: "Times Square", coords: [40.7580, -73.9855] },
        { name: "Central Park", coords: [40.7829, -73.9654] },
        { name: "Statue of Liberty", coords: [40.6892, -74.0445] },
        { name: "Brooklyn Bridge", coords: [40.7061, -73.9969] }
    ];

    return (
        <div className="map-container" style={{ height: "500px", width: "100%" }}>
            <MapContainer
                center={position}
                zoom={12}
                style={{ height: "100%", width: "100%" }}
            >
                <TileLayer
                    url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                    attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                />
                {locations.map((loc, index) => (
                    <Marker key={index} position={loc.coords}>
                        <Popup>{loc.name}</Popup>
                    </Marker>
                ))}
            </MapContainer>
        </div>
    );
};

export default NYCMap;
